SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "凝命神宝制成，朱允炆在奉天殿受贺", "description": "正月初一，凝命神宝制成，朝廷告祭天地和宗庙。朱允炆在奉天殿接受百官朝贺。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年正月辛酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "027ba51d-c110-5184-ae35-d7d64a41a11c"}, {"title": "吴杰平安在深州拦击燕军失利", "description": "吴杰、平安在深州拦击燕军，交战失利。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年正月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dfe428ee-5496-52f5-acb8-4ba292e97b74"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年正月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8d20fa45-b131-53e3-82d3-41f992688009"}, {"title": "明廷在太庙告祭东昌大捷", "description": "朝廷祭祀太庙，报告东昌之战获胜。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年正月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1874bb70-c7c2-5340-b2a5-175f28782265"}, {"title": "齐泰恢复原职", "description": "建文3年（年号对照1401年）正月，齐泰恢复原职。", "start_year": 1401, "end_year": 1401, "time_original": "建文3年（年号对照1401年）正月；公元年核为1401年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "95f56f6c-5a37-505f-8ba2-e315b34a5b21"}, {"title": "盛庸在夹河击败燕军", "description": "盛庸率军在夹河击败燕军，燕将谭渊被杀。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年三月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aaf81159-ab86-57d7-9573-d59993ec919b"}, {"title": "夹河再战，庄得楚智等战死", "description": "双方再次交战，朝廷军队失利，都指挥庄得、楚智等力战而死。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0618f39b-deb6-5dc7-837f-da9da999f82d"}, {"title": "盛庸再次失利后退往德州", "description": "本纪记载，盛庸所部于壬午再次交战，战败后退往德州。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年三月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ded37718-ffa3-5579-95e9-7d99cda06225"}, {"title": "何福率军增援德州", "description": "都督何福率军增援德州。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年三月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "23cb8048-8839-5e36-b201-94fa971980ea"}, {"title": "齐泰再次被贬职", "description": "建文3年（年号对照1401年）闰三月，齐泰再次被贬职。", "start_year": 1401, "end_year": 1401, "time_original": "建文3年（年号对照1401年）闰三月；公元年核为1401年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "e9933b0d-98ab-5078-bd47-359dee3d530f"}, {"title": "吴杰平安在藁城失利后退守真定", "description": "吴杰、平安在藁城与燕军交战失利，退守真定。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年闰三月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c245b9f9-45f9-5e24-ad1b-e8bf368b5d4f"}, {"title": "燕军进掠真定等地", "description": "燕军进掠真定、顺德、广平和大名。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年闰三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "42b1da63-530b-5886-8ebf-0cce9078a8dd"}, {"title": "朱棣上书请停兵，朝廷派薛嵓答复", "description": "朱棣上书请朝廷召还诸将并停止作战。朝廷派大理少卿薛嵓答复。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年闰三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2e6a9a8-421c-5904-8782-9521640dd3de"}, {"title": "明廷定礼制并颁行各地", "description": "礼制于这月制定完成，朝廷在各地颁行。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年闰三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4574be45-749f-5d69-8554-978e5a03dc42"}, {"title": "盛庸试图截断燕军运粮路线", "description": "盛庸出兵试图截断燕军运粮路线，未能成功。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年五月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ea280acd-cd7e-5c5b-bc62-fd36b7a2a9af"}, {"title": "朱棣再次上书，朝廷扣押其使者", "description": "朱棣再次派使者上书朝廷，朝廷将来使关押入狱。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "29ad4837-42b3-5753-9dfb-912090df04e9"}, {"title": "燕将李远在沛县烧毁运粮船", "description": "燕军将领李远进袭沛县，烧毁运粮船。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年六月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "36540de1-fe2c-566e-b0f9-9d192faa1d09"}, {"title": "袁宇截击燕军失利", "description": "都督袁宇率部拦击燕军，交战失利。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年六月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e411b946-9b3e-5307-b46a-255e71834f68"}, {"title": "燕军进掠彰德", "description": "本纪记载，燕军在七月己丑进掠彰德。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年七月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0b756b50-92b8-5bc2-a36a-8d4593f85588"}, {"title": "平安从真定出兵攻北平", "description": "平安于七月丁酉从真定率军攻打北平。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年七月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0474dd05-cc6f-5b17-bd70-f9d0b01718d6"}, {"title": "房昭经紫荆关进抵易州西水寨", "description": "大同守将房昭率军经紫荆关赶往保定，驻扎在易州西水寨。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年七月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "46d1d1fc-e820-5203-9be9-0a63d3aa7aca"}, {"title": "平安在北平战败后退守真定", "description": "平安在北平与燕将刘江作战失利，退守真定。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年九月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "316e57e3-b3f4-5a8d-8188-943a4f7e2a5a"}, {"title": "真定援军在齐眉山对燕军作战失利", "description": "真定诸将派兵增援房昭，援军与燕王所部在齐眉山交战失利。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年十月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f864af6a-8596-51e0-81c4-296b13885e4e"}, {"title": "杨文进攻永平，在昌黎作战失利", "description": "辽东总兵官杨文出兵攻永平，与燕将刘江在昌黎交战失利。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年十一月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d8d8623b-03fe-524c-a6b5-c4e9c4287819"}, {"title": "平安在杨村击败燕将李彬", "description": "平安率军在杨村击败燕将李彬。", "start_year": 1401, "end_year": 1401, "time_original": "建文三年十一月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e3c4c489-daf9-5c5b-a0f6-887a315f0f9c"}, {"title": "燕军焚毁真定的军用储备", "description": "燕军烧毁真定的军用储备。", "start_year": 1402, "end_year": 1402, "time_original": "建文三年十二月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "baaebd37-b1de-5360-b046-0796d601712e"}, {"title": "明廷命地方查办出使时欺压吏民的中官", "description": "朝廷下诏，奉使的中官若欺压吏民，由事发地主管官署拘押查办。", "start_year": 1402, "end_year": 1402, "time_original": "建文三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "30e76ca7-9d04-522b-ae82-6d6b4340bac8"}, {"title": "梅殷镇守淮安", "description": "本纪记载，这个月驸马都尉梅殷镇守淮安。", "start_year": 1402, "end_year": 1402, "time_original": "建文三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ee21ed12-6961-56b6-bdb9-359bd411ff9d"}, {"title": "《太祖实录》编成", "description": "本纪记载，《太祖实录》在这个月编成。", "start_year": 1402, "end_year": 1402, "time_original": "建文三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f2c74d9-d858-58ac-ac8d-853425b556fe"}, {"title": "明廷召原周王朱橚回京", "description": "朝廷从蒙化召回原周王朱橚，让他在京师居住。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年正月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "94c5823e-e263-5023-904d-e1ebdc80132b"}, {"title": "燕军连取东阿等地，郑华王省遇难", "description": "燕军接连攻占东阿、东平、汶上、兖州和济阳，东平吏目郑华与济阳教谕王省因此身亡。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4697a695-598f-5737-8f8c-3e101de3f761"}, {"title": "徐辉祖率军增援山东", "description": "魏国公徐辉祖领兵增援山东。卷末校记指出正文重复使用甲申，并列出《明史稿》作辛丑的记载。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3d28bfa7-ccd0-57b6-ba5d-b58f5149e16e"}, {"title": "燕军攻下沛县，颜伯玮等身亡", "description": "燕军攻下沛县，知县颜伯玮、主簿唐子清、典史黄谦都在战事中身亡。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7efacb45-6b5d-55bb-ba60-fa377d93fcdb"}, {"title": "燕军逼近徐州", "description": "本纪记载燕军于正月癸丑逼近徐州。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年正月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "73129afc-17d5-5e3e-a736-f4ecee1af828"}, {"title": "何福等驻济宁，盛庸驻淮上", "description": "都督何福与陈晖、平安驻军济宁，盛庸所部驻在淮水一带。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年二月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1c08294a-c316-5f24-aaa3-ec0f4da2f897"}, {"title": "明廷重新厘定品官勋阶", "description": "朝廷重定品官所授的勋阶。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年二月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "035dd833-f1a6-5c29-a58b-bdf2171226d6"}, {"title": "宿州失守前平安在淝河作战失利", "description": "燕军攻打宿州。平安追到淝河，杀死燕将王真后遇伏战败，宿州随后失守。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "042da009-7f8d-53fa-8412-e515f639375f"}, {"title": "何福平安在小河击败燕军", "description": "何福和平安在小河击败燕军，燕将陈文在战事中被杀。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5520b4f9-8066-5814-b30b-d9325f98ca7b"}, {"title": "徐辉祖等人在齐眉山击败燕军", "description": "徐辉祖等人在齐眉山击败燕军，燕将李斌被杀。燕军惧怕，谋划北撤。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "65013ddc-287f-5e26-ad39-5f16afa6295e"}, {"title": "朱允炆误信燕军北撤而召回徐辉祖", "description": "朱允炆听信燕军已经北撤的消息，召徐辉祖返回。何福所部因而失去援助。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8a377d75-9e23-5f2a-99ed-5ad54493af97"}, {"title": "朝廷军队在灵璧战败，多名将领官员被俘", "description": "朝廷将领在灵璧与燕军大战，军队失利，陈晖、平安、礼部侍郎陈性善和大理寺卿彭与明均被俘。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c699831a-03db-57ac-bd5f-24af46440ad4"}, {"title": "杨文赴援济南，辽东军在直沽溃散", "description": "杨文率辽东军赶往济南增援，部队在直沽溃散。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d22398a2-a52a-5670-8e10-8050e923d36e"}, {"title": "盛庸军在淮上溃散，燕军渡淮进向扬州", "description": "盛庸所部在淮水一带溃散，燕军渡过淮水赶往扬州。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5227fe96-fd06-5a18-b928-08da54757de8"}, {"title": "王礼等归附燕军，王彬和崇刚遇难", "description": "指挥王礼等转而归附燕军，御史王彬和指挥崇刚因此身亡。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "39872de0-527b-5a5e-a790-e5648bca92b8"}, {"title": "朝廷军队在六合迎战燕军失利", "description": "燕军抵达六合，朝廷各部迎战失利。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "efbb131b-4d04-5613-b7f7-cbfbcea33540"}, {"title": "朱允炆下诏征兵勤王", "description": "朱允炆下诏令各地兵力入援，并派御史大夫练子宁、侍郎黄观和修撰王叔英分别到各处征兵。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "45256c56-7872-564b-9002-2875fc1b65f2"}, {"title": "朱允炆召齐泰黄子澄返回", "description": "朝廷召齐泰、黄子澄返回。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b1c846b9-78ef-5492-864c-122b77efdab9"}, {"title": "姚善等地方官起兵入援", "description": "苏州知府姚善、宁波知府王璡、徽州知府陈彦回和乐平知县张彦方各自募集部队，入援朝廷。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fbdd8403-5836-52a7-bcb4-d576f67b3076"}, {"title": "明廷派庆成郡主赴燕军议和", "description": "朝廷派庆成郡主到燕军商谈割地停兵。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b62bc2aa-9b71-581f-9bd8-803cf2d7873d"}, {"title": "盛庸在浦子口迎战燕军", "description": "盛庸率水军在浦子口先击败燕军，后来再次交战失利。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "caff1fae-fd9b-50f3-b4e8-f3e0eb42da71"}, {"title": "陈瑄率水军归附燕军", "description": "都督佥事陈瑄率水军转而归附燕军。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2d22496f-4730-5354-b331-ea69ff447abb"}, {"title": "燕军渡江，盛庸在高资港战败", "description": "燕军渡江。盛庸在高资港迎战，所部战败。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e9d5bbc-1028-581d-ae46-3d93aeb8a610"}, {"title": "镇江守将童俊归附燕军", "description": "镇江守将童俊转而归附燕军。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3423384-7495-575d-97b2-d4bbf8c89589"}, {"title": "燕军到达龙潭", "description": "本纪记载，燕军于六月庚申到达龙潭。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d087d2ee-64bc-524e-b9aa-2909960b95ba"}, {"title": "明廷命诸王守都城并派李景隆等继续交涉", "description": "朝廷命诸王分守都城，派李景隆、兵部尚书茹瑺和都督王佐到燕军重提原先议和条件。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "72459365-fb3b-5885-9beb-5f1eed9436c1"}, {"title": "明廷再派谷王安王议和，燕军未接受", "description": "朝廷又派谷王朱橞和安王朱楹前往燕军，燕军没有接受交涉。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c5a6c30b-4a9b-59b1-9024-204cba2015bf"}, {"title": "明廷派使者持密信催促援兵", "description": "朝廷派使者持以蜡封缄的密信到各处，催援兵进京。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c12648fe-f759-53c5-bcec-984dd86e9be9"}, {"title": "燕军进入金川门，都城失守", "description": "燕军进逼金川门。左都督徐增寿谋划内应，被处死。谷王朱橞和李景隆转而接纳燕军入城，都城失守。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e1235ee2-01af-5534-b9ad-5e187b9fd796"}, {"title": "宫中起火后朱允炆下落不明", "description": "本纪记载，宫中起火，朱允炆此后的下落不明。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "363e9957-980d-54e3-bf69-a23cf691fd4d"}, {"title": "本纪记燕王遣使取尸并安葬", "description": "本纪载燕王派中使从火中取出其所称帝后尸体，随后在壬申日安葬。卷内也记建文帝的下落不明。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6a36a70-9104-550d-908d-76522840bdf5"}, {"title": "杨行祥自称建文帝被查办", "description": "本纪记载，正统五年，一名僧人从云南来到广西，自称建文帝。思恩知府岑瑛上报后查出他是钧州人杨行祥，已九十多岁。杨行祥入狱四个月后死亡，十二名同谋僧人被发往辽东戍守。 按原历纪年，事情发生在公元1440至1441年之间。", "start_year": null, "end_year": null, "time_original": "正统五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "333872a4-06e8-5840-a38b-91d7d6903fc7"}, {"title": "清廷议定朱允炆谥号", "description": "清乾隆元年，清廷下诏召臣工集议，追谥朱允炆为恭闵惠皇帝。 按原历纪年，事情发生在公元1736至1737年之间。", "start_year": null, "end_year": null, "time_original": "乾隆元年", "dynasty": "清", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5f2c9e92-f551-5607-a058-be3b02917b61"}]'::jsonb)
