INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "朱允炆在奉天殿接受朝贺。", "citation": "《明史》卷4·本纪第四·恭闵帝·mingshi-2f603db3d81e-p000910；建文三年正月辛酉朔", "note": "原文：辛酉朔，凝命神寶成，告天地宗廟，御奉天殿受朝賀。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "e1cfda8d-5dd9-5204-b543-851dfd8f3508", "subject_id": "76ea9485-acac-508c-a6ae-e2532462c03e", "source_id": "da6fa30f-22c7-5e74-91b2-10ef48c120a3"}, {"subject_table": "person", "field_path": "description", "claim_text": "本纪另载朱允炆可能由地道出亡的说法。", "citation": "《明史》卷4·本纪第四·恭闵帝·mingshi-2f603db3d81e-p000927；建文四年六月失都后的异说", "note": "原文：或云帝由地道出亡。；核对说明：单列为原文异说，不能据此决定朱允炆的下落。", "status": "draft", "id": "8f2410be-2c9c-5207-8839-f6d54cb5663f", "subject_id": "76ea9485-acac-508c-a6ae-e2532462c03e", "source_id": "b1f70d98-60de-5eac-a92b-3c713d24d54f"}, {"subject_table": "person", "field_path": "description", "claim_text": "《明史》史臣赞称朱允炆即位之初亲贤好学。", "citation": "《明史》卷4·本纪第四·恭闵帝·mingshi-2f603db3d81e-p000929；卷末回顾", "note": "原文：贊曰：惠帝天資仁厚。踐阼之初，親賢好學，召用方孝孺等。；核对说明：保留为史臣赞语。", "status": "draft", "id": "070644ac-e9ca-5fce-a1ac-6aa1c1cc3754", "subject_id": "76ea9485-acac-508c-a6ae-e2532462c03e", "source_id": "080ce3ed-574d-53ae-aa3f-d80412b439ea"}, {"subject_table": "event", "field_path": "description", "claim_text": "正月初一，凝命神宝制成，朝廷告祭天地和宗庙。朱允炆在奉天殿接受百官朝贺。", "citation": "《明史》卷4·本纪第四·恭闵帝·mingshi-2f603db3d81e-p000910；建文三年正月辛酉朔", "note": "原文：辛酉朔，凝命神寶成，告天地宗廟，御奉天殿受朝賀。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "e60e2716-8e6f-55a0-99b0-9d2385cd30d3", "subject_id": "027ba51d-c110-5184-ae35-d7d64a41a11c", "source_id": "da6fa30f-22c7-5e74-91b2-10ef48c120a3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历建文三年正月辛酉朔。DDBC历表换算所据为1401-01-24至1401-01-24，据此核对公元发生年份。", "citation": "《明史》卷4·本纪第四·恭闵帝·mingshi-2f603db3d81e-p000910；建文三年正月辛酉朔", "note": "原文：辛酉朔，凝命神寶成，告天地宗廟，御奉天殿